	if !errors.Is(err, ErrQueryTooShort) {
		t.Fatalf("err = %v", err)
	}
	if f.calls.Load() != 0 {
		t.Errorf("walks = %d, want 0", f.calls.Load())
	}
}

func TestWalkKeyNeverFormatsCredentials(t *testing.T) {
	s := &walkShare{}
	key := s.keyFor(member("k", "", "alice-user", "hunter2-secret"))
	for _, verb := range []string{"%#v", "%+v", "%v"} {
		out := fmt.Sprintf(verb, key)
		for _, leak := range []string{"alice-user", "hunter2-secret"} {
			if contains(out, leak) {
				t.Errorf("%s leaks %q: %s", verb, leak, out)
			}
		}
	}
}

func contains(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}
